css:
.d1117-tube,.d1117-b1,.d1117-b2,.d1117-syr,.d1117-up,.d1117-pl{transform-box:fill-box}
.d1117-tube{transform-origin:left center;animation:d1117-drop 3.6s ease-in infinite}
.d1117-b1{transform-origin:left center;animation:d1117-s1 3.6s ease-in-out infinite}
.d1117-b2{transform-origin:left center;animation:d1117-s2 3.6s ease-in-out infinite}
.d1117-t{animation:d1117-pop 3.6s ease-in-out infinite}
.d1117-syr{transform-origin:center;animation:d1117-jab 3.4s ease-in-out infinite}
.d1117-pl{transform-origin:center bottom;animation:d1117-push 3.4s ease-in-out infinite}
.d1117-up{transform-origin:center bottom;animation:d1117-rise 3.4s ease-out infinite}
@keyframes d1117-drop{0%,40%{transform:none;opacity:1}85%,100%{transform:translateY(60px) rotate(25deg);opacity:0}}
@keyframes d1117-s1{0%,20%,60%,100%{transform:rotate(0)}40%{transform:rotate(14deg)}}
@keyframes d1117-s2{0%,20%,60%,100%{transform:rotate(0)}40%{transform:rotate(-14deg)}}
@keyframes d1117-pop{0%,38%{opacity:0}48%,100%{opacity:1}}
@keyframes d1117-jab{0%,15%{transform:translateY(-8px)}40%,60%{transform:translateY(4px)}85%,100%{transform:translateY(-8px)}}
@keyframes d1117-push{0%,35%{transform:translateY(0)}55%,100%{transform:translateY(14px)}}
@keyframes d1117-rise{0%,45%{transform:translateY(16px);opacity:0}70%{transform:none;opacity:1}100%{transform:translateY(-8px);opacity:0}}
@media (prefers-reduced-motion:reduce){.d1117-tube{opacity:.3}.d1117-up{opacity:1}.d1117-t{opacity:1}}
